"); } /// `__rt_builtin_filter_id(ptr, len) -> id`, zero when the name is not built in. /// /// Input: AArch64 x0 = name pointer, x1 = name length. /// x86_64 rdi = name pointer, rsi = name length. pub fn emit_builtin_filter_id(emitter: &mut Emitter) { if emitter.target.arch == Arch::X86_64 { emit_builtin_filter_id_linux_x86_64(emitter); return; } emitter.blank(); emitter.comment("--- runtime: resolve a built-in stream filter name ---"); emitter.label_global("__rt_builtin_filter_id"); abi::emit_symbol_address(emitter, "x9", "_bf_table"); emitter.label("__rt_bfid_entry"); emitter.instruction("ldr x10, [x9]"); // candidate name pointer emitter.instruction("cbz x10, __rt_bfid_miss"); // null pointer terminates the table emitter.instruction("ldr x11, [x9, #8]"); // candidate name length
